const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var geometry = ee.Geometry.Rectangle([75.07, 26.87, 75.27, 27.07]); // Lake Sambhar bounding box

  // 2. Data Acquisition & Check - JRC Monthly Water History
  var col_sept = ee.ImageCollection('JRC/GSW1_3/MonthlyHistory')
                    .filterDate('2018-09-01', '2018-09-30');
  var col_april = ee.ImageCollection('JRC/GSW1_3/MonthlyHistory')
                    .filterDate('2019-04-01', '2019-04-30');

  var septSize = col_sept.size().getInfo();
  var aprilSize = col_april.size().getInfo();

  // Check for empty collections
  if (septSize === 0 || aprilSize === 0) {
    console.log(`2018-09 Images: ${septSize}, 2019-04 Images: ${aprilSize}`);
    console.log('<answer>C1</answer>');
    return;
  }

  var sept2018 = col_sept.first();
  var april2019 = col_april.first();

  // 3. Processing - Water mask (value 2 = water)
  var waterMaskSept = sept2018.select('water').eq(2); // 1 for water, 0 otherwise
  var waterMaskApril = april2019.select('water').eq(2);

  // Count water pixels (at 100m scale to avoid timeout)
  var scale = 100;
  var countSept = waterMaskSept.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('water').getInfo();

  var countApril = waterMaskApril.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('water').getInfo();

  // Check for no valid pixels
  if (countSept === 0 && countApril === 0) {
    console.log(`Water pixels (Sept): ${countSept}, (April): ${countApril}`);
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate water area in km² (pixel area at scale)
  var pixelArea = scale * scale / 1e6; // km² per pixel
  var areaSept = countSept * pixelArea;
  var areaApril = countApril * pixelArea;

  console.log(`2018-09 Water Area: ${areaSept.toFixed(2)} km² (pixels: ${countSept})`);
  console.log(`2019-04 Water Area: ${areaApril.toFixed(2)} km² (pixels: ${countApril})`);

  // 4. Validation & Final Answer
  if (areaSept === null || areaApril === null || 
      isNaN(areaSept) || isNaN(areaApril) || 
      areaSept < 0 || areaApril < 0) {
    console.log('<answer>C3</answer>');
  } else if (areaApril < areaSept) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
